steps.script:
var boyz = GameState.state["units"]["U_BOYZ_E"]
var cal = GameState.state["units"]["U_CALADIUS_GRAV-TANK_E"]["models"][0]
return tree.root.get_node("TerrainManager").unit_has_cover_11e(boyz, cal)

var sc = tree.root.get_node("Main/ShootingController")
sc.test_hover_target_id = "U_BOYZ_E"
return sc.current_hover_forecast != null

var sc = tree.root.get_node("Main/ShootingController")
var f = sc.current_hover_forecast
return f.bs == int(RulesEngine.get_weapon_profile(f.weapon_id).bs) + 1 and f.base_bs == 2 and f.bs_no_cover == 2 and f.in_cover and f.cover_bs_delta == 1

var card = tree.root.get_node("Main/ShootingController/HoverForecast")
if not card.get_node("Body/CoverRow").visible or not card.get_node("Body/CoverRow/CoverIcon").visible:
	return "cover row hidden"
return card.get_node("Body/CoverRow/CoverLabel").text

var sc = tree.root.get_node("Main/ShootingController")
var card = tree.root.get_node("Main/ShootingController/HoverForecast")
var f = sc.current_hover_forecast
var title = card.get_node("Body/Title").get_parsed_text()
return title.contains(str(f.weapon_name)) and title.contains("Boyz") and card.get_node("Body/Stats").get_parsed_text().contains("BS 3+")

var card = tree.root.get_node("Main/ShootingController/HoverForecast")
var r: Rect2 = card.get_global_rect()
var vp: Rect2 = card.get_viewport_rect()
return card.visible and r.size.x > 200.0 and r.size.y > 100.0 and r.position.x >= vp.position.x + 4.0 and r.position.y >= vp.position.y + 4.0 and r.end.x <= vp.end.x - 4.0 and r.end.y <= vp.end.y - 4.0

var card = tree.root.get_node("Main/ShootingController/HoverForecast")
var vp: Rect2 = card.get_viewport_rect()
var home: Vector2 = card.anchor_screen
var bad = []
for a in [Vector2(vp.end.x - 3.0, vp.position.y + 3.0), Vector2(vp.end.x - 3.0, vp.end.y - 3.0), Vector2(vp.position.x + 3.0, vp.end.y - 3.0), Vector2(vp.position.x + 3.0, vp.position.y + 3.0)]:
	card.move_to_anchor(a)
	var r: Rect2 = card.get_global_rect()
	if r.position.x < vp.position.x or r.position.y < vp.position.y or r.end.x > vp.end.x or r.end.y > vp.end.y:
		bad.append(str(a) + ' -> ' + str(r))
card.move_to_anchor(home)
return 'ok' if bad.is_empty() else ', '.join(bad)

var card = tree.root.get_node("Main/ShootingController/HoverForecast")
var tip = tree.root.get_node_or_null("Main/TokenHoverTooltip")
if tip == null or not tip.visible:
	return "stats card not shown"
if card.get_global_rect().intersects(tip.get_global_rect()):
	return "overlap"
return "clear"

